function el(tag,cls,...children){const n=document.createElement(tag);if(cls)n.className=cls;for(const child of children.flat(Infinity)){if(child!==null&&child!==undefined)n.append(child instanceof Node?child:document.createTextNode(String(child)));}return n;}
