const dateFormat=new Intl.DateTimeFormat(cfg.locale,{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
const monthFormat=new Intl.DateTimeFormat(cfg.locale,{month:'long',year:'numeric',timeZone:'UTC'});
const moneyFormat=new Intl.NumberFormat(cfg.locale,{style:'currency',currency:cfg.currency});
const dayMs=86400000;
function today(){const f=new Intl.DateTimeFormat('en-CA',{timeZone:cfg.timeZone,year:'numeric',month:'2-digit',day:'2-digit'});const parts=Object.fromEntries(f.formatToParts(new Date()).map(p=>[p.type,p.value]));return Date.UTC(+parts.year,+parts.month-1,+parts.day);}
function iso(ms){return new Date(ms).toISOString().slice(0,10);}
function parseRelease(raw){
  if(typeof raw!=='string'||!raw.trim())return {kind:'unknown',label:'Brak daty',sort:Infinity};
  const s=raw.trim();let m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/),y,mo,d;
  if(m){[,y,mo,d]=m.map(Number);}else if((m=s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/))){[,d,mo,y]=m.map(Number);}
  if(y!==undefined){const dt=new Date(0);dt.setUTCFullYear(y,mo-1,d);dt.setUTCHours(0,0,0,0);if(y>0&&dt.getUTCFullYear()===y&&dt.getUTCMonth()===mo-1&&dt.getUTCDate()===d){const ms=dt.getTime();return{kind:'day',label:dateFormat.format(dt),sort:ms,ms,month:iso(ms).slice(0,7),iso:iso(ms)};}}
  if((m=s.match(/^(\d{4})-(\d{2})$/))&&+m[1]>0&&+m[2]>=1&&+m[2]<=12){const dt=new Date(0);dt.setUTCFullYear(+m[1],+m[2]-1,1);dt.setUTCHours(0,0,0,0);return{kind:'month',label:monthFormat.format(dt)+' · dzień nieznany',sort:dt.getTime(),month:s};}
  if((m=s.match(/^(\d{4})(?:-Q([1-4]))?$/i))&&+m[1]>0){const dt=new Date(0);dt.setUTCFullYear(+m[1],m[2]?(+m[2]-1)*3:0,1);dt.setUTCHours(0,0,0,0);return{kind:m[2]?'quarter':'year',label:m[2]?`${m[1]} · kwartał ${m[2]}`:`${m[1]} · termin nieznany`,sort:dt.getTime()};}
  return{kind:/^(TBA|TBD)$/i.test(s)?'unknown':'invalid',label:/^(TBA|TBD)$/i.test(s)?'Do ustalenia':s,sort:Infinity};
}
function monthLabel(key){if(!key)return 'Termin nieustalony';const dt=new Date(`${key}-01T00:00:00Z`);return Number.isNaN(dt.getTime())?'Termin nieustalony':monthFormat.format(dt);}
function cents(price){if(price===null||price===undefined||price===''||typeof price==='boolean')return null;const n=Number(price);return Number.isFinite(n)&&n>=0&&n<=99999999.99?Math.round(n*100):null;}
function money(value){return value===null?'Brak ceny':moneyFormat.format(value/100);}
function cheapest(g){const valid=(g.offers||[]).map(o=>cents(o.price)).filter(v=>v!==null);return valid.length?Math.min(...valid):null;}
function inBudget(g){return g.in_budget!==false&&g.in_budget!==0&&g.in_budget!=='0'&&g.in_budget!=='false';}
function dateSort(a,b){const x=parseRelease(a.release_date).sort,y=parseRelease(b.release_date).sort;return x===y?String(a.title).localeCompare(String(b.title),cfg.locale):x<y?-1:1;}
function countdown(g){const r=parseRelease(g.release_date);if(r.kind!=='day')return 'Termin niepotwierdzony';const d=Math.round((r.ms-today())/dayMs);return d===0?'Premiera dzisiaj':d===1?'1 dzień do premiery':d>1?`${d} dni do premiery`:'Po premierze';}
function nextRelease(games){return games.filter(g=>{const r=parseRelease(g.release_date);return r.kind==='day'&&r.ms>=today();}).sort(dateSort)[0];}
function safeUrl(value,{cover=false}={}){if(typeof value!=='string'||!value.trim())return null;if(demo&&cover&&/^assets\/(crimson(?:-hero)?|orion|northern)\.webp$/.test(value))return "/v3/"+value;try{const u=new URL(value);return (cover?u.protocol==='https:':['https:','http:'].includes(u.protocol))&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function gameId(g){const id=g.game_id??g.id;return Number.isSafeInteger(id)&&id>0?id:null;}
function ref(g,edit=false){const id=gameId(g);if(id)return {game_id:id};return edit?{original_title:g.title,original_platform:g.platform}:{title:g.title,platform:g.platform};}
function sameGame(a,b){const id=gameId(a),other=gameId(b);return id&&other?id===other:a.title===b.title&&a.platform===b.platform;}
function gameCover(g,cls=''){const cover=el('div',`cover ${cls}`,icon('gamepad'));const url=safeUrl(g.cover_url,{cover:true});if(url){const im=el('img');im.alt='';im.loading='lazy';im.decoding='async';im.referrerPolicy='no-referrer';im.addEventListener('error',()=>im.remove(),{once:true});im.src=url;cover.append(im);}return cover;}
function platform(g){const p=String(g.platform||'Nieznana');const low=p.toLowerCase();return el('span',`platform ${/ps|playstation/.test(low)?'ps':/xbox/.test(low)?'xbox':/ns|switch|nintendo/.test(low)?'nintendo':low==='pc'?'pc':''}`,low==='ns2'?'Switch 2':p);}
function priceText(g){const v=cheapest(g);return v===null?'Brak ceny':money(v);}
function sampleData(){const now=today(),g=(id,title,platform,days,art,offers,in_budget=true)=>({game_id:id,title,platform,release_date:iso(now+days*dayMs),cover_url:`assets/${art}.webp`,offers,in_budget});return {games:[g(1,'Crimson Horizon','PS5',10,'crimson',[{store_name:'Media Markt',price:279,order_number:'DEMO-1042',url:null},{store_name:'RTV Euro AGD',price:289.99,order_number:null,url:null}]),g(2,'Echoes of Orion','PC',17,'orion',[{store_name:'Steam',price:229,order_number:null,url:null}]),g(3,'Northern Realm','NS2',52,'northern',[{store_name:'X-Kom',price:199,order_number:null,url:null}],false)],collection:[{id:101,title:'Astral Expedition',platform:'PS5',date_added:iso(now-16*dayMs),release_date:iso(now-40*dayMs),cover_url:null},{id:102,title:'Forgotten Citadel',platform:'PC',date_added:iso(now-25*dayMs),release_date:iso(now-48*dayMs),cover_url:null},{id:103,title:'Neon Drift',platform:'NS2',date_added:iso(now-36*dayMs),release_date:iso(now-57*dayMs),cover_url:null}]};}
const state={games:[],collection:[],ready:false,busy:false,stale:false,error:'',view:'dashboard',search:'',platform:'all',budgetFilter:'all',sort:'date',layout:'list',cal:new Date(today()),selectedDay:null,authMode:'login',epoch:0,editGame:null,detailsGame:null,demoCounter:1000};
let toastTimer,confirmResolve=null;
function toast(message,error=false){clearTimeout(toastTimer);const n=$('toast');n.textContent=message;n.className=`toast${error?' error':''}`;n.hidden=false;toastTimer=setTimeout(()=>n.hidden=true,6500);}
function errorMessage(data,status){const detail=data?.detail;if(Array.isArray(detail))return detail.map(d=>`${(d.loc||[]).filter(p=>p!=='body').join('.')}: ${d.msg||'Nieprawidłowa wartość'}`).join('; ');if(typeof detail==='string')return detail;if(status===429)return 'Za dużo prób. Spróbuj później.';if(status>=500)return 'Serwer API zwrócił błąd. Sprawdź logi Render.';return `Operacja nie powiodła się (HTTP ${status}).`;}
class APIError extends Error{constructor(message,status=0){super(message);this.status=status;}}
function clearSession(){if(!demo){for(const k of ['access_token','user_id','username'])localStorage.removeItem(k);}session.token='';session.username='';session.id='';state.epoch++;state.games=[];state.collection=[];state.ready=false;state.busy=false;state.stale=false;state.error='';state.editGame=null;state.detailsGame=null;state.search='';state.platform='all';state.budgetFilter='all';state.sort='date';$('search').value='';for(const id of ['editor','details','confirm-dialog','menu-dialog','account-dialog'])if($(id).open)$(id).close();$('view').replaceChildren();$('account-body').replaceChildren();$('status').hidden=true;}
function authScreen(message=''){if(demo){location.href='?';return;}clearSession();$('app').hidden=true;$('auth').hidden=false;setAuthMode('login');$('auth-password').value='';if(message)showAuthError(message);}
async function api(path,{method='GET',body,auth=true}={}){if(demo)throw new Error('Tryb demo nie wywołuje API');const epoch=state.epoch;const headers={Accept:'application/json'};if(auth){if(!session.token)throw new APIError('Zaloguj się ponownie.',401);headers.Authorization=`Bearer ${session.token}`;}let payload;if(body instanceof URLSearchParams){headers['Content-Type']='application/x-www-form-urlencoded';payload=body;}else if(body!==undefined){headers['Content-Type']='application/json';payload=JSON.stringify(body);}let res;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),cfg.timeoutMs);try{res=await fetch(cfg.apiBase.replace(/\/$/,'')+path,{method,headers,body:payload,signal:controller.signal,cache:'no-store',credentials:'omit',redirect:'error'});const data=await res.json().catch(()=>null);if(epoch!==state.epoch)throw new APIError('Sesja została zmieniona.',-1);if(!res.ok){const message=errorMessage(data,res.status);if(auth&&res.status===401)authScreen('Sesja wygasła. Zaloguj się ponownie.');throw new APIError(message,res.status);}return data;}catch(err){if(err instanceof APIError)throw err;throw new APIError(err.name==='AbortError'?'Przekroczono czas oczekiwania.':'Nie można połączyć się z API. Sprawdź połączenie i logi Render.');}finally{clearTimeout(timer);}}
function showAuthError(message){text('auth-error',message);$('auth-error').hidden=!message;}
let signupConfig=null;
function setAuthMode(mode){state.authMode=mode;const register=mode==='register';$('auth-legal').hidden=!register;$('auth-accept').required=register;$('auth-accept').checked=false;text('auth-title',register?'Utwórz konto':'Witaj ponownie');text('auth-subtitle',register?'Zacznij budować własną listę gier.':'Zaloguj się, aby wrócić do swojej listy.');text('auth-submit',register?'Zarejestruj się':'Zaloguj się');text('auth-switch-label',register?'Masz już konto?':'Nie masz konta?');text('auth-toggle',register?'Zaloguj się':'Zarejestruj się');$('auth-password').minLength=register?12:1;$('auth-password').autocomplete=register?'new-password':'current-password';$('auth-hint').hidden=!register;showAuthError('');}
async function authSubmit(e){e.preventDefault();if($('auth-submit').disabled)return;const u=$('auth-username').value.trim(),p=$('auth-password').value;if(!u||!p){showAuthError('Podaj nazwę użytkownika i hasło.');return;}const reg=state.authMode==='register';$('auth-submit').disabled=true;$('auth-toggle').disabled=true;showAuthError('');text('auth-submit',reg?'Tworzenie konta…':'Logowanie…');try{if(reg){if(!signupConfig?.signup_enabled||!$('auth-accept').checked){showAuthError('Zapoznaj się z dokumentami i zaakceptuj regulamin.');return;}await api('/register',{method:'POST',body:{username:u,password:p,accept_terms:$('auth-accept').checked,policy_version:signupConfig?.policy_version},auth:false});setAuthMode('login');$('auth-password').value='';toast('Konto utworzone. Możesz się zalogować.');return;}const data=await api('/login',{method:'POST',body:new URLSearchParams({username:u,password:p}),auth:false});if(typeof data?.access_token!=='string'||!data.access_token||data.user_id==null)throw new APIError('Nieprawidłowa odpowiedź logowania.');session.token=data.access_token;session.username=String(data.username||u);session.id=String(data.user_id);localStorage.setItem('access_token',session.token);localStorage.setItem('user_id',session.id);localStorage.setItem('username',session.username);$('auth-password').value='';state.epoch++;showApp();await reload();}catch(err){showAuthError(err.message);}finally{$('auth-submit').disabled=false;$('auth-toggle').disabled=false;text('auth-submit',state.authMode==='register'?'Zarejestruj się':'Zaloguj się');}}
function showApp(){ $('auth').hidden=true;$('app').hidden=false;$('demo-notice').hidden=!demo;text('profile-name',session.username||'Mój profil');text('profile-detail',demo?'Dane przykładowe':'Moje konto');text('avatar',(session.username||'PH').slice(0,2).toUpperCase());text('logout-label',demo?'Wyjdź z demo':'Wyloguj się');state.view=views[location.hash.slice(1)]?location.hash.slice(1):'dashboard';render();}
function connection(status,label){$('connection-dot').className=status;text('connection-text',label);}
async function reload({afterWrite=false}={}){if(demo){state.ready=true;state.stale=false;state.error='';connection('online','Tryb demo · lokalnie');render();return true;}if(!session.token||state.busy)return false;const epoch=state.epoch;state.busy=true;state.error='';render();connection('','Łączenie z API...');try{const [games,collection]=await Promise.all([api('/get_preorders'),api('/get_collection')]);if(epoch!==state.epoch)return false;if(!Array.isArray(games)||!Array.isArray(collection))throw new APIError('Nieprawidłowy format odpowiedzi API.');state.games=games;state.collection=collection;state.ready=true;state.stale=false;state.error='';connection('online','Połączono z API');return true;}catch(err){if(epoch!==state.epoch)return false;state.stale=state.ready;state.error=(afterWrite?'Operacja zapisana, ale nie udało się odświeżyć danych. ':'')+err.message;connection('offline','Brak połączenia');return false;}finally{if(epoch===state.epoch){state.busy=false;render();}}}
function goto(view){if(!views[view])return;state.view=view;state.search='';$('search').value='';if(location.hash!==`#${view}`)history.pushState(null,'',`#${view}`);if($('menu-dialog').open)$('menu-dialog').close();render();window.scrollTo({top:0,behavior:'instant'});}
function navItem(view,mobile=false){const [symbol,label]=views[view];const b=btn('',()=>goto(view),mobile?'':'nav-btn');b.replaceChildren(icon(symbol),el('span','',mobile&&view==='collection'?'Kolekcja':label));if(state.view===view){b.classList.add('active');b.setAttribute('aria-current','page');}return b;}
function renderNav(){const nav=$('desktop-nav');nav.replaceChildren(...Object.keys(views).map(v=>navItem(v)));$('extra-nav').replaceChildren(...Object.keys(views).map(v=>navItem(v)),btn(demo?'Wyjdź z demo':'Wyloguj się',logout,'nav-btn logout','logout'));const mobile=$('mobile-nav');const add=btn('',()=>openEditor(),'add-mobile');add.replaceChildren(el('span','',icon('plus')),el('span','','Dodaj'));add.disabled=!canWrite();mobile.replaceChildren(navItem('dashboard',true),navItem('preorders',true),add,navItem('calendar',true),navItem('collection',true));}
function canWrite(){return state.ready&&!state.busy&&!state.stale;}
function renderStatus(){const n=$('status');n.hidden=!state.error;if(state.error){n.replaceChildren(icon('info'),el('span','',state.error+(state.stale?' Wyświetlane dane mogą być nieaktualne.':'')),btn('Ponów',()=>reload(),'btn secondary small-btn'));}}
function render(){if($('app').hidden)return;const v=views[state.view];text('view-title',v[2]);text('view-subtitle',v[3]);text('view-kicker',state.view==='dashboard'?'TWÓJ GAMING COMMAND CENTER':'PREORDER HUB / '+v[1].toUpperCase());$('refresh').disabled=state.busy;$('add').disabled=!canWrite();$('search').disabled=!state.ready||!['dashboard','preorders','collection'].includes(state.view);renderNav();renderStatus();const root=$('view');if(!state.ready){if(state.error)root.replaceChildren(empty('Nie udało się pobrać danych','Nie pokazujemy danych przykładowych zamiast Twojej kolekcji.',btn('Spróbuj ponownie',()=>reload(),'btn primary','refresh')));else root.replaceChildren(el('div','loading',el('div','spinner'),'Ładowanie Twoich gier…'));return;}const renderers={dashboard:renderDashboard,preorders:renderPreorders,calendar:renderCalendarPage,budget:renderBudgetPage,collection:renderCollection,settings:renderSettings};root.replaceChildren(renderers[state.view]());}
function matches(g){const q=state.search.trim().toLocaleLowerCase(cfg.locale);return !q||[g.title,g.platform,...(g.offers||[]).map(o=>o.store_name)].some(s=>String(s||'').toLocaleLowerCase(cfg.locale).includes(q));}
